"""Generate web/src/generated_models.rs from the GLBs in assets/models.

The 3D renderer must load every authored model, not a hand-maintained list —
otherwise newly generated assets silently never appear in game. Called by
build.sh before wasm-pack.
"""
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
names = sorted(p.stem for p in (ROOT / "assets" / "models").glob("*.glb"))
if not names:
    raise SystemExit("no GLBs found in assets/models")

out = ROOT / "web" / "src" / "generated_models.rs"
lines = [
    "// GENERATED by scripts/gen_model_list.py — do not edit by hand.",
    "pub const GLB_MODELS: &[&str] = &[",
]
lines += [f'    "{n}",' for n in names]
lines.append("];")
out.write_text("\n".join(lines) + "\n")
print(f"[gen_model_list] {len(names)} models -> {out}")
